package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoMomentNoteCopyTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun catalog()=VideoMomentNotes(5000,listOf(VideoMomentNote(1,"Start"),VideoMomentNote(1250,"A | ß"),VideoMomentNote(4000,"界")))
 @Test fun exactMillisecondUnicodeAndPipeTextRoundtripsWithoutMetadata(){val value=catalog();val text=VideoMomentNoteText.format(value);assertEquals("0.001 | Start\n1.250 | A | ß\n4.000 | 界",text);assertEquals(value.notes,VideoMomentNoteText.parse(text,value.durationMs));assertFalse(text.contains("content://"));assertFalse(text.contains("guest-basic"))}
 @Test fun maximumCatalogAndTimestampRoundtripExactly(){val duration=Int.MAX_VALUE.toLong()+1;val value=VideoMomentNotes(duration,(0 until 99).map{VideoMomentNote(it.toLong(),"界".repeat(80))}+VideoMomentNote(Int.MAX_VALUE.toLong(),"Last"));val text=VideoMomentNoteText.format(value);assertTrue(text.length<=16000);assertTrue(text.endsWith("2147483.647 | Last"));assertEquals(value.notes,VideoMomentNoteText.parse(text,duration))}
 @Test fun emptyOrUnimportableNotesAreRefusedBeforeCopy(){assertTrue(runCatching{VideoMomentNoteText.format(VideoMomentNotes(5000))}.isFailure);assertTrue(runCatching{VideoMomentNoteText.format(VideoMomentNotes(Int.MAX_VALUE.toLong()+2,listOf(VideoMomentNote(Int.MAX_VALUE.toLong()+1,"Too far"))))}.isFailure)}
 @Test fun formatUsesDecimalPointsRegardlessOfDeviceLocale(){val old=java.util.Locale.getDefault();try{for(locale in listOf(java.util.Locale.FRANCE,java.util.Locale.forLanguageTag("ar"),java.util.Locale.forLanguageTag("tr"))){java.util.Locale.setDefault(locale);assertTrue(VideoMomentNoteText.format(catalog()).contains("1.250 | A"));assertEquals(catalog().notes,VideoMomentNoteText.parse(VideoMomentNoteText.format(catalog()),5000))}}finally{java.util.Locale.setDefault(old)}}
 @Test fun actualClipboardFactoryCreatesOnlySensitivePlainText(){val text=VideoMomentNoteText.format(catalog());val clip=VideoMomentNoteClipboard.create(text);assertEquals(1,clip.itemCount);assertTrue(clip.description.hasMimeType("text/plain"));assertEquals("Source moment notes",clip.description.label);assertEquals(text,clip.getItemAt(0).text.toString());assertNull(clip.getItemAt(0).uri);assertNull(clip.getItemAt(0).intent);assertNull(clip.getItemAt(0).htmlText);assertTrue(clip.description.extras.getBoolean(VideoMomentNoteClipboard.SENSITIVE_EXTRA))}
 @Test fun clipboardFactoryRefusesEmptyAndOversizedPayloads(){for(text in listOf(""," ","x".repeat(16001)))assertTrue(runCatching{VideoMomentNoteClipboard.create(text)}.isFailure)}
 private fun fixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoActionReview>{val a=activity();val d=dialog();val r=VideoActionReview();r.open(d);set(a,"momentReviewRequest",r);set(a,"momentReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 private fun copy(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoActionReview,review:VideoCaptionReviewState,load:()->VideoMomentNotes={catalog()},write:(String)->Unit={}):Boolean=call(a,"performMomentNoteCopy",d,r,review,catalog(),load,write)as Boolean
 @Test fun approvedCopyWritesExactReviewedTextOnceWithoutChangingProjectOrNotes(){val(a,d,r)=fixture();val review=capture(a);val p=get(a,"project")as VideoEditProject;val clips=p.segments;val music=p.soundtrack;var count=0;var copied="";assertTrue(copy(a,d,r,review,write={copied=it;count++}));assertEquals(VideoMomentNoteText.format(catalog()),copied);assertEquals(1,count);assertFalse(copy(a,d,r,review,write={count++}));assertEquals(1,count);assertSame(clips,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo)}
 @Test fun anyCatalogChangeConsumesApprovalWithoutClipboardWrite(){val original=catalog();for(next in listOf(original.remove(original.notes[0]),original.rename(original.notes[0],"Changed"),original.add(VideoMomentNote(4500,"Added")),VideoMomentNotes(5001,original.notes))){val(a,d,r)=fixture();val review=capture(a);try{copy(a,d,r,review,{next}){fail("copied stale notes")};fail("accepted changed catalog")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalStateException)};assertTrue(r.isClosed);assertFalse(copy(a,d,r,review,write={fail("revived")}))}}
 @Test fun staleForegroundSourceDurationModeGenerationRecoveryAndBusyRefuseBeforeRead(){for(flag in listOf("pause","source","duration","mode","generation","recovery","busy")){val(a,d,r)=fixture();val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"generation"->set(a,"captionReviewGeneration",review.generation+1);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,copy(a,d,r,review,{fail("read stale");catalog()}){fail("write")})}}
 @Test fun sourceChangeDuringReadAndReadFailurePreventClipboardAndConsume(){for(flag in listOf("source","read")){val(a,d,r)=fixture();val review=capture(a);try{copy(a,d,r,review,{if(flag=="read")error("failed read");set(a,"source",Uri.parse("content://synthetic/other"));catalog()}){fail("copied")};fail("accepted") }catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalStateException)};assertTrue(r.isClosed)}}
 @Test fun oldHiddenOrUntrackedDialogCannotCopyOrConsumeSuccessor(){for(flag in listOf("old","hidden","untracked")){val(a,d,r)=fixture();val review=capture(a);val next=if(flag=="old")dialog()else null;when(flag){"old"->{r.open(next!!);set(a,"momentReviewDialog",next);set(a,"captionReviewDialogs",linkedSetOf(next))};"hidden"->showing(d,false);else->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>())};assertFalse(copy(a,d,r,review,{fail("read old");catalog()}){fail("write old")});if(next!=null){assertTrue(r.owns(next));assertTrue(copy(a,next,r,review))}}}
 @Test fun cancellationAndBlockedEntryPrecedeClipboardOrWidgets(){val(a,d,r)=fixture();val review=capture(a);r.dismiss(d);assertFalse(copy(a,d,r,review,{fail("read cancelled");catalog()}){fail("copy cancelled")});for(flag in listOf("pause","busy","recovery")){val b=activity();when(flag){"pause"->set(b,"workspaceActive",false);"busy"->set(b,"saving",true);else->set(b,"recoveryBytes",byteArrayOf(1))};call(b,"copyMomentNotes");assertNull(get(b,"momentReviewRequest"));assertNull(get(b,"captionReviewDialogs"));assertFalse((get(b,"project")as VideoEditProject).canUndo)}}
}
